    97→
    98→pub const Tokenizer = struct {
    99→    source: []const u8,
   100→    pos: usize,
   101→    line: usize,
   102→    column: usize,
   103→    line_start: usize,
   104→
   105→    pub fn init(source: []const u8) Tokenizer {
   106→        return .{
   107→            .source = source,
   108→            .pos = 0,
   109→            .line = 1,
   110→            .column = 1,
   111→            .line_start = 0,
   112→        };
   113→    }
   114→
   115→    pub fn nextToken(self: *Tokenizer) Token {
   116→        // Skip whitespace and comments
   117→        while (self.pos < self.source.len) {
   118→            const c = self.source[self.pos];
   119→
   120→            if (isWhitespace(c)) {
   121→                if (c == '\n') {
   122→                    self.line += 1;
   123→                    self.line_start = self.pos + 1;
   124→                    self.column = 1;
   125→                } else {
   126→                    self.column += 1;
   127→                }
   128→                self.pos += 1;
   129→                continue;
   130→            }
   131→
   132→            // Line comment
   133→            if (c == '/' and self.peek() == '/') {
   134→                while (self.pos < self.source.len and self.source[self.pos] != '\n') {
   135→                    self.pos += 1;
   136→                }
   137→                continue;
   138→            }
   139→
   140→            // Block comment
   141→            if (c == '/' and self.peek() == '*') {
   142→                self.pos += 2;
   143→                self.column += 2;
   144→                while (self.pos < self.source.len - 1) {
   145→                    if (self.source[self.pos] == '*' and self.source[self.pos + 1] == '/') {
   146→                        self.pos += 2;
   147→                        self.column += 2;
   148→                        break;
   149→                    }
   150→                    if (self.source[self.pos] == '\n') {
   151→                        self.line += 1;
   152→                        self.line_start = self.pos + 1;
   153→                        self.column = 1;
   154→                    } else {
   155→                        self.column += 1;
   156→                    }
   157→                    self.pos += 1;
   158→                }
   159→                continue;
   160→            }
   161→
   162→            break;
   163→        }
   164→
   165→        if (self.pos >= self.source.len) {
   166→            return Token{
   167→                .tag = .eof,
   168→                .loc = .{
   169→                    .line = self.line,
   170→                    .column = self.column,
   171→                    .start = self.pos,
   172→                    .end = self.pos,
   173→                },
   174→            };
   175→        }
   176→
   177→        const start = self.pos;
   178→        const start_column = self.column;
   179→        const c = self.source[self.pos];
   180→
   181→        // Number literal
   182→        if (isDigit(c)) {
   183→            return self.scanNumber(start, start_column);
   184→        }
   185→
   186→        // String literal
   187→        if (c == '"') {
   188→            return self.scanString(start, start_column);
   189→        }
   190→
   191→        // Character literal
   192→        if (c == '\'') {
   193→            return self.scanCharLiteral(start, start_column);
   194→        }
   195→
   196→        // Identifier or keyword
   197→        if (isIdentifierStart(c)) {
   198→            return self.scanIdentifier(start, start_column);
   199→        }
   200→
   201→        // Operators and delimiters
   202→        return self.scanOperator(start, start_column);
   203→    }
   204→
   205→    fn scanNumber(self: *Tokenizer, start: usize, start_column: usize) Token {
   206→        while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
   207→            self.pos += 1;
   208→            self.column += 1;
   209→        }
   210→
   211→        // Float
   212→        if (self.pos < self.source.len and self.source[self.pos] == '.') {
   213→            self.pos += 1;
   214→            self.column += 1;
   215→
   216→            while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
   217→                self.pos += 1;
   218→                self.column += 1;
   219→            }
   220→
   221→            return Token{
   222→                .tag = .float,
   223→                .start = start,
   224→                .end = self.pos,
   225→                .line = self.line,
   226→                .column = start_column,
   227→            };
   228→        }
   229→
   230→        return Token{
   231→            .tag = .integer,
   232→            .start = start,
   233→            .end = self.pos,
   234→            .line = self.line,
   235→            .column = start_column,
   236→        };
   237→    }
   238→
   239→    fn scanString(self: *Tokenizer, start: usize, start_column: usize) Token {
   240→        self.pos += 1; // Skip opening "
   241→        self.column += 1;
   242→
   243→        while (self.pos < self.source.len and self.source[self.pos] != '"') {
   244→            if (self.source[self.pos] == '\\') {
   245→                self.pos += 2;
   246→                self.column += 2;
   247→            } else if (self.source[self.pos] == '\n') {
   248→                self.line += 1;
   249→                self.line_start = self.pos + 1;
   250→                self.column = 1;
   251→                self.pos += 1;
   252→            } else {
   253→                self.pos += 1;
   254→                self.column += 1;
   255→            }
   256→        }
   257→
   258→        if (self.pos < self.source.len) {
   259→            self.pos += 1; // Skip closing "
   260→            self.column += 1;
   261→        }
   262→
   263→        return Token{
   264→            .tag = .string,
   265→            .start = start,
   266→            .end = self.pos,
   267→            .line = self.line,
   268→            .column = start_column,
   269→        };
   270→    }
   271→
   272→    fn scanCharLiteral(self: *Tokenizer, start: usize, start_column: usize) Token {
   273→        self.pos += 1;
   274→        self.column += 1;
   275→
   276→        if (self.source[self.pos] == '\\') {
   277→            self.pos += 2;
   278→            self.column += 2;
   279→        } else {
   280→            self.pos += 1;
   281→            self.column += 1;
   282→        }
   283→
   284→        if (self.pos < self.source.len and self.source[self.pos] == '\'') {
   285→            self.pos += 1;
   286→            self.column += 1;
   287→        }
   288→
   289→        return Token{
   290→            .tag = .char_literal,
   291→            .start = start,
   292→            .end = self.pos,
   293→            .line = self.line,
   294→            .column = start_column,
   295→        };
   296→    }
   297→
   298→    fn scanIdentifier(self: *Tokenizer, start: usize, start_column: usize) Token {
   299→        while (self.pos < self.source.len and isIdentifierContinue(self.source[self.pos])) {
   300→            self.pos += 1;
   301→            self.column += 1;
   302→        }
   303→
   304→        const text = self.source[start..self.pos];
   305→        const tag = getKeywordTag(text) orelse .identifier;
   306→
   307→        return Token{
   308→            .tag = tag,
   309→            .start = start,
   310→            .end = self.pos,
   311→            .line = self.line,
   312→            .column = start_column,
   313→        };
   314→    }
   315→
   316→    fn scanOperator(self: *Tokenizer, start: usize, start_column: usize) Token {
   317→        const c = self.source[self.pos];
   318→        self.pos += 1;
   319→        self.column += 1;
   320→
   321→        const tag: Token.Tag = switch (c) {
   322→            '+' => .plus,
   323→            '-' => {
   324→                if (self.pos < self.source.len and self.source[self.pos] == '>') {
   325→                    self.pos += 1;
   326→                    self.column += 1;
   327→                    return Token{ .tag = .arrow, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   328→                }
   329→                return Token{ .tag = .minus, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   330→            },
   331→            '*' => .star,
   332→            '/' => .slash,
   333→            '%' => .percent,
   334→            '=' => {
   335→                if (self.pos < self.source.len and self.source[self.pos] == '=') {
   336→                    self.pos += 1;
   337→                    self.column += 1;
   338→                    return Token{ .tag = .equal_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   339→                }
   340→                return Token{ .tag = .equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   341→            },
   342→            '!' => {
   343→                if (self.pos < self.source.len and self.source[self.pos] == '=') {
   344→                    self.pos += 1;
   345→                    self.column += 1;
   346→                    return Token{ .tag = .bang_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   347→                }
   348→                return Token{ .tag = .bang, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   349→            },
   350→            '<' => {
   351→                if (self.pos < self.source.len) {
   352→                    if (self.source[self.pos] == '=') {
   353→                        self.pos += 1;
   354→                        self.column += 1;
   355→                        return Token{ .tag = .less_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   356→                    } else if (self.source[self.pos] == '<') {
   357→                        self.pos += 1;
   358→                        self.column += 1;
   359→                        return Token{ .tag = .lshift, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   360→                    }
   361→                }
   362→                return Token{ .tag = .less, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   363→            },
   364→            '>' => {
   365→                if (self.pos < self.source.len) {
   366→                    if (self.source[self.pos] == '=') {
   367→                        self.pos += 1;
   368→                        self.column += 1;
   369→                        return Token{ .tag = .greater_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   370→                    } else if (self.source[self.pos] == '>') {
   371→                        self.pos += 1;
   372→                        self.column += 1;
   373→                        return Token{ .tag = .rshift, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   374→                    }
   375→                }
   376→                return Token{ .tag = .greater, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   377→            },
   378→            '&' => .ampersand,
   379→            '|' => .pipe,
   380→            '^' => .caret,
   381→            '~' => .tilde,
   382→            '.' => .dot,
   383→            '?' => .question,
   384→            ':' => {
   385→                if (self.pos < self.source.len and self.source[self.pos] == ':') {
   386→                    self.pos += 1;
   387→                    self.column += 1;
   388→                    return Token{ .tag = .double_colon, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   389→                }
   390→                return Token{ .tag = .colon, .start = start, .end = self.pos, .line = self.line, .column = start_column };
   391→            },
   392→            '(' => .lparen,
   393→            ')' => .rparen,
   394→            '{' => .lbrace,
   395→            '}' => .rbrace,
   396→            '[' => .lbracket,
   397→            ']' => .rbracket,
   398→            ';' => .semicolon,
   399→            ',' => .comma,
   400→            else => .invalid,
   401→        };
   402→
   403→        return Token{
   404→            .tag = tag,
   405→            .start = start,
   406→            .end = self.pos,
   407→            .line = self.line,
   408→            .column = start_column,
   409→        };
   410→    }
   411→
   412→    fn peek(self: *Tokenizer) u8 {
   413→        if (self.pos + 1 >= self.source.len) return 0;
   414→        return self.source[self.pos + 1];
   415→    }
   416→};
   417→
   418→fn isWhitespace(c: u8) bool {
   419→    return c == ' ' or c == '\t' or c == '\n' or c == '\r';
   420→}
   421→
   422→fn isDigit(c: u8) bool {
   423→    return c >= '0' and c <= '9';
   424→}
   425→
   426→fn isAlpha(c: u8) bool {
   427→    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_';
   428→}
   429→
   430→fn isIdentifierStart(c: u8) bool {
   431→    return isAlpha(c);
   432→}
   433→
   434→fn isIdentifierContinue(c: u8) bool {
   435→    return isAlpha(c) or isDigit(c);
   436→}
   437→
   438→fn getKeywordTag(text: []const u8) ?Token.Tag {
   439→    return switch (std.meta.stringToEnum(Token.Tag, text ++ "_") orelse return null) {
   440→        inline .fn_, .const_, .var_, .if_, .else_, .while_, .for_, .return_, .struct_, .enum_, .union_, .error_, .try_, .catch_, .pub_, .inline_, .comptime_, .true_, .false_, .null_, .and_, .or_, .not_ => |tag| tag,
   441→        else => null,
   442→    };
   443→}
   444→
   445→// Test
   446→pub fn main() !void {
   447→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
   448→    defer _ = gpa.deinit();
   449→    const allocator = gpa.allocator();
   450→
   451→    const source = "fn add(a: i32, b: i32) -> i32 { return a + b; }";
   452→
   453→    var tokenizer = Tokenizer.init(source);
   454→    var tokens = std.ArrayList(Token).init(allocator);
   455→    defer tokens.deinit();
   456→
   457→    while (true) {
   458→        const token = tokenizer.nextToken();
   459→        try tokens.append(token);
   460→        std.debug.print("Token: {s:15} = \"{s}\"\n", .{ @tagName(token.tag), token.lexeme(source) });
   461→
   462→        if (token.tag == .eof) break;
   463→    }
   464→}
